public static long CountOf(string[] words, string target)
{
    var counts = new Dictionary<string, long>();
    foreach (var w in words)
    {
        if (counts.ContainsKey(w)) counts[w]++;
        else counts[w] = 1;
    }
    return counts.ContainsKey(target) ? counts[target] : 0;
}

