public static long GrowthAfterBump(long[] values)
{
    var bumped = values;
    for (int i = 0; i < bumped.Length; i++)
    {
        bumped[i] = bumped[i] + 1;
    }
    long before = 0;
    foreach (var v in values) before += v;
    long after = 0;
    foreach (var v in bumped) after += v;
    return after - before;
}

